def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    rectangles = []
    for color in counts:
        if color == background:
            continue

        # Prefix sums make rectangle counts quick to compute.
        prefix = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            for c in range(w):
                prefix[r + 1][c + 1] = (
                    prefix[r][c + 1] + prefix[r + 1][c] - prefix[r][c]
                    + (grid[r][c] == color)
                )

        def rect_count(r1, c1, r2, c2):
            return (prefix[r2 + 1][c2 + 1] - prefix[r1][c2 + 1]
                    - prefix[r2 + 1][c1] + prefix[r1][c1])

        candidates = []
        for r1 in range(h):
            for r2 in range(r1 + 1, h):
                for c1 in range(w):
                    for c2 in range(c1 + 1, w):
                        area = (r2 - r1 + 1) * (c2 - c1 + 1)
                        n = rect_count(r1, c1, r2, c2)
                        if n / area < 0.84:
                            continue
                        # Reject expansions whose outer edge is mostly not the object color.
                        if any(sum(grid[r][c] == color for c in range(c1, c2 + 1)) / (c2 - c1 + 1) < 0.6
                               for r in range(r1, r2 + 1)):
                            continue
                        if any(sum(grid[r][c] == color for r in range(r1, r2 + 1)) / (r2 - r1 + 1) < 0.6
                               for c in range(c1, c2 + 1)):
                            continue
                        candidates.append((r1, c1, r2, c2))

        # Keep only maximal rectangles for this color.
        for box in candidates:
            r1, c1, r2, c2 = box
            if not any(
                other != box and other[0] <= r1 and other[1] <= c1
                and other[2] >= r2 and other[3] >= c2
                for other in candidates
            ):
                rectangles.append((box, color))

    out = [[background for _ in range(w)] for _ in range(h)]
    for (r1, c1, r2, c2), color in rectangles:
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                out[r][c] = color
    return out
